#
# stand-present-or-explain.sh — отвечает, есть ли поднятый кластер, и если нет,
# ГОВОРИТ об этом так, чтобы читатель сводки не принял следствие за причину.
#
# ─── ПРЕДМЕТ (#728) ─────────────────────────────────────────────────────────
#
# Шаг диагностики объявляется с функцией состояния (`always()`) — то есть
# исполняется и тогда, когда работа сорвалась ЗАДОЛГО до стенда. Кластера в этот
# момент нет, обращение к нему отказывает, и рядом с НАЗВАННОЙ причиной в сводке
# встаёт второй красный шаг с посторонним текстом. Один отказ выглядит как два,
# и второй из них не поломка вовсе: он эхо первого.
#
# У диагностики два очевидных исхода, и оба неверны поодиночке:
#
#   — падать за компанию: даёт то самое эхо, ради которого заведён #728;
#   — молчать (погасить код возврата и всё): тогда в журнале остаются восемь
#     строк «журнал недоступен» без единого слова о ПРИЧИНЕ, и читатель идёт
#     искать её в продукте. Тише, но не лучше.
#
# Поэтому здесь третий: НЕ ПАДАЕМ И НЕ МОЛЧИМ. Скрипт отвечает кодом возврата
# (0 — кластер отвечает, 1 — нет), а на отказе печатает, что именно случилось и
# почему это следствие, а не причина.
#
# ─── КАК ЗВАТЬ ──────────────────────────────────────────────────────────────
#
#   "$GITHUB_WORKSPACE/.github/scripts/stand-present-or-explain.sh" "<чей стенд>" || exit 0
#
# `|| exit 0` — часть формы, а не украшение: без него код 1 под `bash -e`
# (а GitHub исполняет тело шага именно так) снова уронит шаг.
#
# Свойство держит гейт дерева `internal/repohygiene`
# `TestClusterDiagnosticsNeverEchoAMissingStand`, а поведение САМОГО скрипта —
# исполняемая проба рядом с ним: она подкладывает в PATH отвечающий и
# отказывающий инструмент и требует разных исходов.

set -u

what="${1:-стенд}"

# Предел обращения — свой. Без него запрос к мёртвому адресу ждёт минутами и
# съедает предел ШАГА: один невнятный исход менялся бы на другой, столь же
# невнятный. Величина вынесена наружу, чтобы проба могла её сузить.
probe_timeout="${KACHO_CLUSTER_PROBE_TIMEOUT:-20s}"

# Сообщение — одной строкой: аннотация GitHub многострочной не бывает, а «%»
# в данных ломает разбор команды рабочего процесса.
say_absent() {
    local detail="$1"
    local msg
    msg="${what}: ${detail} Значит стенд не поднимался либо его подъём оборвался ВЫШЕ — виновник назван ТЕМ шагом, а не этим. Диагностика пропущена и вердикта не выносит: второе красное рядом с настоящей причиной делает один отказ похожим на два."
    printf '%s\n' "УСЛОВИЕ НЕ СОЗДАНО: ${msg}"
    msg=${msg//%/%25}
    printf '::notice title=Кластера нет — это следствие, а не причина::%s\n' "$msg"
}

if ! command -v kubectl >/dev/null 2>&1; then
    say_absent "kubectl на ранере нет вовсе, то есть подготовка не дошла даже до его установки."
    exit 1
fi

answer=$(kubectl cluster-info --request-timeout="$probe_timeout" 2>&1)
rc=$?
if [ "$rc" -eq 0 ]; then
    exit 0
fi

# Печатаем ПЕРВУЮ строку ответа самого инструмента: «ноль находок» обязано быть
# отличимо от «ноль спрошенного», а доказательство того, что спрашивали, — это
# его собственный текст, а не наше утверждение о нём.
first=$(printf '%s\n' "$answer" | head -1 | tr -d '\r' | cut -c1-200)
say_absent "обращение к кластеру отказано (код ${rc}): ${first}."
exit 1
